import { readFile, rename, unlink, writeFile } from "node:fs/promises";
import { dirname, basename, join, resolve } from "node:path";

type Status = "open" | "done";

type Task = {
  id: number;
  title: string;
  tags: string[];
  status: Status;
  createdAt: string;
  due?: string;
  completedAt?: string;
};

type Database = {
  nextId: number;
  tasks: Task[];
};

class CliError extends Error {}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isIsoTimestamp(value: unknown): value is string {
  return typeof value === "string" && !Number.isNaN(Date.parse(value));
}

function isDate(value: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const [year, month, day] = value.split("-").map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  return date.getUTCFullYear() === year && date.getUTCMonth() === month - 1 && date.getUTCDate() === day;
}

function requireDate(value: string, name: string): string {
  if (!isDate(value)) throw new CliError(`${name} must be a valid YYYY-MM-DD date`);
  return value;
}

function normalizeTag(value: string): string {
  const tag = value.trim().toLowerCase();
  if (!tag) throw new CliError("tags must not be empty");
  return tag;
}

function parseTags(value: string): string[] {
  return [...new Set(value.split(",").map(normalizeTag))];
}

function validateDatabase(value: unknown): Database {
  if (!isRecord(value) || !Number.isSafeInteger(value.nextId) || value.nextId < 1 || !Array.isArray(value.tasks)) {
    throw new CliError("database is malformed");
  }
  const ids = new Set<number>();
  let maxId = 0;
  for (const task of value.tasks) {
    if (!isRecord(task) || !Number.isSafeInteger(task.id) || task.id < 1 || ids.has(task.id) ||
        typeof task.title !== "string" || !task.title.trim() ||
        !Array.isArray(task.tags) || !task.tags.every((tag) => typeof tag === "string" && tag === normalizeTag(tag)) ||
        new Set(task.tags).size !== task.tags.length ||
        (task.status !== "open" && task.status !== "done") || !isIsoTimestamp(task.createdAt) ||
        (task.due !== undefined && (typeof task.due !== "string" || !isDate(task.due))) ||
        (task.completedAt !== undefined && !isIsoTimestamp(task.completedAt)) ||
        (task.status === "done" && task.completedAt === undefined) ||
        (task.status === "open" && task.completedAt !== undefined)) {
      throw new CliError("database is malformed");
    }
    ids.add(task.id);
    maxId = Math.max(maxId, task.id);
  }
  if (value.nextId <= maxId) throw new CliError("database is malformed");
  return value as Database;
}

async function loadDatabase(path: string): Promise<Database> {
  try {
    return validateDatabase(JSON.parse(await readFile(path, "utf8")));
  } catch (error: unknown) {
    if (isRecord(error) && error.code === "ENOENT") return { nextId: 1, tasks: [] };
    if (error instanceof CliError) throw error;
    throw new CliError("database is malformed");
  }
}

async function saveDatabase(path: string, database: Database): Promise<void> {
  const directory = dirname(path);
  const temporary = join(directory, `.${basename(path)}.${process.pid}.${crypto.randomUUID()}.tmp`);
  try {
    await writeFile(temporary, `${JSON.stringify(database, null, 2)}\n`, "utf8");
    await rename(temporary, path);
  } catch (error) {
    await unlink(temporary).catch(() => undefined);
    throw error;
  }
}

function localToday(): string {
  const now = new Date();
  const pad = (number: number) => String(number).padStart(2, "0");
  return `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;
}

function parseId(value: string | undefined): number {
  if (!value || !/^\d+$/.test(value)) throw new CliError("ID must be a positive integer");
  const id = Number(value);
  if (!Number.isSafeInteger(id) || id < 1) throw new CliError("ID must be a positive integer");
  return id;
}

function parseFlags(arguments_: string[], allowed: readonly string[]): Map<string, string> {
  const flags = new Map<string, string>();
  for (let index = 0; index < arguments_.length; index += 2) {
    const flag = arguments_[index];
    const value = arguments_[index + 1];
    if (!flag.startsWith("--") || !allowed.includes(flag) || value === undefined || value.startsWith("--") || flags.has(flag)) {
      throw new CliError("invalid command arguments");
    }
    flags.set(flag, value);
  }
  return flags;
}

async function run(arguments_: string[]): Promise<unknown> {
  const [command, ...rest] = arguments_;
  if (!command) throw new CliError("missing command");
  const file = resolve(process.env.TASKBOARD_FILE || ".taskboard.json");

  if (command === "add") {
    const flags = parseFlags(rest, ["--title", "--tags", "--due"]);
    const title = flags.get("--title")?.trim();
    if (!title) throw new CliError("--title is required and must not be empty");
    const database = await loadDatabase(file);
    const task: Task = { id: database.nextId++, title, tags: flags.has("--tags") ? parseTags(flags.get("--tags")!) : [], status: "open", createdAt: new Date().toISOString() };
    if (flags.has("--due")) task.due = requireDate(flags.get("--due")!, "--due");
    database.tasks.push(task);
    await saveDatabase(file, database);
    return task;
  }

  if (command === "list") {
    const flags = parseFlags(rest, ["--status", "--tag", "--overdue"]);
    const status = flags.get("--status");
    if (status !== undefined && status !== "open" && status !== "done") throw new CliError("--status must be open or done");
    const tag = flags.has("--tag") ? normalizeTag(flags.get("--tag")!) : undefined;
    const overdue = flags.has("--overdue") ? requireDate(flags.get("--overdue")!, "--overdue") : undefined;
    const database = await loadDatabase(file);
    return database.tasks.filter((task) =>
      (status === undefined || task.status === status) &&
      (tag === undefined || task.tags.includes(tag)) &&
      (overdue === undefined || (task.status === "open" && task.due !== undefined && task.due < overdue)),
    ).sort((a, b) => a.id - b.id);
  }

  if (command === "done" || command === "delete") {
    if (rest.length !== 1) throw new CliError(`${command} requires exactly one ID`);
    const id = parseId(rest[0]);
    const database = await loadDatabase(file);
    const index = database.tasks.findIndex((task) => task.id === id);
    if (index === -1) throw new CliError(`task ${id} does not exist`);
    if (command === "delete") {
      const [deleted] = database.tasks.splice(index, 1);
      await saveDatabase(file, database);
      return deleted;
    }
    const task = database.tasks[index];
    if (task.status === "open") {
      task.status = "done";
      task.completedAt = new Date().toISOString();
      await saveDatabase(file, database);
    }
    return task;
  }

  if (command === "stats") {
    if (rest.length !== 0) throw new CliError("stats does not accept arguments");
    const tasks = (await loadDatabase(file)).tasks;
    const open = tasks.filter((task) => task.status === "open");
    return { total: tasks.length, open: open.length, done: tasks.length - open.length, overdue: open.filter((task) => task.due !== undefined && task.due < localToday()).length };
  }
  throw new CliError(`unknown command: ${command}`);
}

try {
  console.log(JSON.stringify(await run(process.argv.slice(2))));
} catch (error) {
  const message = error instanceof Error ? error.message : "unexpected error";
  console.error(`taskboard: ${message}`);
  console.log(JSON.stringify({ error: message }));
  process.exitCode = 1;
}

